//==============================================================================
// Testbench: atmospheric_light_tb
// Description: Unit test cho atmospheric_light module
// 
// Test Strategy:
//   - Load test patterns từ hex file (generated by Python)
//   - Test với multiple frames (mỗi frame có nhiều pixels)
//   - Verify module tìm đúng pixel có dark_ch cao nhất
//   - Compare với golden output
//
// Pattern format:
//   FFFFFFFF = Frame Start
//   DD_BBGGRR = Pixel data (dark_ch, B, G, R)
//   EEEEEEEE = Frame End
//
// Golden format:
//   BBGGRR = Expected A (B, G, R)
//==============================================================================

`timescale 1ns/10ps
`define CYCLE 10.0
`define MAX_PATTERNS 100
`define MAX_FRAMES 20

module atmospheric_light_tb();

    //==========================================================================
    // Clock Generation
    //==========================================================================
    logic clk = 0;
    always #(`CYCLE/2) clk = ~clk;

    //==========================================================================
    // DUT Signals
    //==========================================================================
    logic        rst_n;
    logic        frame_start;
    logic        frame_end;
    logic        valid;
    logic [23:0] rgb_in;
    logic [7:0]  dark_ch;
    logic [7:0]  A_R, A_G, A_B;
    logic        o_valid;

    //==========================================================================
    // DUT Instance
    //==========================================================================
    atmospheric_light dut (
        .i_clk         (clk),
        .i_rst_n       (rst_n),
        .i_frame_start (frame_start),
        .i_frame_end   (frame_end),
        .i_valid       (valid),
        .i_rgb         (rgb_in),
        .i_dark_ch     (dark_ch),
        .o_A_R         (A_R),
        .o_A_G         (A_G),
        .o_A_B         (A_B),
        .o_valid       (o_valid)
    );

    //==========================================================================
    // Pattern and Golden Data
    //==========================================================================
    reg [31:0] pattern_mem [0:`MAX_PATTERNS-1];
    reg [23:0] golden_mem  [0:`MAX_FRAMES-1];
    
    integer pattern_count = 0;
    integer golden_count = 0;
    integer err_count = 0;
    integer frame_num = 0;
    integer i;
    
    //==========================================================================
    // Load Pattern and Golden Files
    //==========================================================================
    initial begin
        // Initialize memories
        for (i = 0; i < `MAX_PATTERNS; i = i + 1)
            pattern_mem[i] = 32'h0;
        for (i = 0; i < `MAX_FRAMES; i = i + 1)
            golden_mem[i] = 24'h0;
        
        // Load files
        $readmemh("../07_golden_output/pattern_atmospheric_light.hex", pattern_mem);
        $readmemh("../07_golden_output/golden_atmospheric_light.hex", golden_mem);
        
        // Count valid patterns (until we hit uninitialized)
        pattern_count = 0;
        while (pattern_count < `MAX_PATTERNS && pattern_mem[pattern_count] !== 32'hxxxxxxxx) begin
            pattern_count = pattern_count + 1;
        end
        
        $display("# Loaded %0d pattern entries", pattern_count);
    end

    //==========================================================================
    // Main Test Sequence
    //==========================================================================
    initial begin
        $display("\n# ====================================================");
        $display("# Atmospheric Light Testbench - Frame-based Testing");
        $display("# ====================================================\n");

        // Initialize
        rst_n <= 0;
        frame_start <= 0;
        frame_end <= 0;
        valid <= 0;
        rgb_in <= 0;
        dark_ch <= 0;
        
        // Reset
        repeat(3) @(posedge clk);
        rst_n <= 1;
        repeat(2) @(posedge clk);

        // Process patterns
        i = 0;
        frame_num = 0;
        
        while (i < pattern_count) begin
            // Check for Frame Start marker
            if (pattern_mem[i] == 32'hFFFFFFFF) begin
                $display("\n# --- Frame %0d ---", frame_num + 1);
                
                // Pulse frame_start
                @(posedge clk);
                frame_start <= 1;
                @(posedge clk);
                frame_start <= 0;
                
                i = i + 1;
                
                // Process pixels until Frame End
                while (i < pattern_count && pattern_mem[i] != 32'hEEEEEEEE) begin
                    @(posedge clk);
                    valid <= 1;
                    dark_ch <= pattern_mem[i][31:24];
                    rgb_in <= pattern_mem[i][23:0];
                    
                    $display("#   Pixel: dc=%0d, RGB=(%0d,%0d,%0d)", 
                             pattern_mem[i][31:24],
                             pattern_mem[i][7:0],    // R
                             pattern_mem[i][15:8],   // G
                             pattern_mem[i][23:16]); // B
                    
                    i = i + 1;
                end
                
                // End of pixel stream
                @(posedge clk);
                valid <= 0;
                
                // Skip Frame End marker
                if (pattern_mem[i] == 32'hEEEEEEEE)
                    i = i + 1;
                
                // Pulse frame_end
                @(posedge clk);
                frame_end <= 1;
                @(posedge clk);
                frame_end <= 0;
                
                // Wait for output
                @(posedge clk);
                @(posedge clk);
                
                // Check result
                if (A_R === golden_mem[frame_num][7:0] && 
                    A_G === golden_mem[frame_num][15:8] && 
                    A_B === golden_mem[frame_num][23:16]) begin
                    $display("#   Result: PASS ✓");
                    $display("#   Got: A=(R=%0d, G=%0d, B=%0d)", A_R, A_G, A_B);
                end else begin
                    $display("#   Result: FAIL ✗");
                    $display("#   Got: A=(R=%0d, G=%0d, B=%0d)", A_R, A_G, A_B);
                    $display("#   Exp: A=(R=%0d, G=%0d, B=%0d)", 
                             golden_mem[frame_num][7:0],
                             golden_mem[frame_num][15:8],
                             golden_mem[frame_num][23:16]);
                    err_count = err_count + 1;
                end
                
                frame_num = frame_num + 1;
            end else begin
                // Skip non-marker entries (shouldn't happen with proper file)
                i = i + 1;
            end
        end

        // Final Report
        repeat(5) @(posedge clk);
        $display("\n# ====================================================");
        $display("#          ATMOSPHERIC LIGHT FINAL REPORT");
        $display("# ====================================================");
        $display("#  Total frames tested: %0d", frame_num);
        if (err_count == 0) begin
            $display("#  ✓ ALL TESTS PASSED!");
        end else begin
            $display("#  ✗ FAILED: %0d / %0d frames", err_count, frame_num);
        end
        $display("# ====================================================\n");

        $finish;
    end

    //==========================================================================
    // Timeout Watchdog
    //==========================================================================
    initial begin
        #100000;
        $display("# ERROR: Simulation timeout!");
        $finish;
    end

endmodule